# Definition for InfiniteStream.
# class InfiniteStream:
#     def next(self) -> int:
#         pass
class Solution:
    def findPattern(self, stream: 'InfiniteStream', pattern: List[int]) -> int:
        m = len(pattern)
        buf = []
        i = 0
        while True:
            buf.append(stream.next())
            i += 1
            if len(buf) > m:
                buf.pop(0)
            if len(buf) == m and buf == pattern:
                return i - m

