/**
 * Definition for InfiniteStream.
 * class InfiniteStream {
 * public:
 *     InfiniteStream(vector<int> bits);
 *     int next();
 * };
 */
class Solution {
public:
    int findPattern(InfiniteStream* stream, vector<int>& pattern) {
        int m = pattern.size(), i = 0;
        deque<int> buf;
        while (true) {
            buf.push_back(stream->next());
            i++;
            if ((int)buf.size() > m) buf.pop_front();
            if ((int)buf.size() == m && equal(buf.begin(), buf.end(), pattern.begin()))
                return i - m;
        }
    }
};

