/**
 * Definition for InfiniteStream.
 * class InfiniteStream {
 *     public InfiniteStream(int[] bits);
 *     public int next();
 * }
 */
class Solution {
    public int findPattern(InfiniteStream stream, int[] pattern) {
        int m = pattern.length, i = 0;
        Deque<Integer> buf = new ArrayDeque<>();
        while (true) {
            buf.addLast(stream.next());
            i++;
            if (buf.size() > m) buf.pollFirst();
            if (buf.size() == m) {
                boolean ok = true;
                int idx = 0;
                for (int v : buf) if (v != pattern[idx++]) { ok = false; break; }
                if (ok) return i - m;
            }
        }
    }
}

