class Solution {
public:
    int findPattern(InfiniteStream* stream, vector<int>& pattern) {
        const long long MOD = (1LL << 61) - 1, BASE = 131;
        int m = pattern.size();
        long long hp = 0;
        for (int b : pattern) hp = (hp * BASE + b) % MOD;
        long long power = 1;
        for (int k = 0; k < m - 1; k++) power = power * BASE % MOD;
        long long h = 0;
        deque<int> win;
        int c = 0, start = 0;
        while (true) {
            int b = stream->next();
            h = (h * BASE + b) % MOD;
            if (c == m) {
                h = ((h - win.front() * power) % MOD + MOD) % MOD;
                win.pop_front();
                start++;
            } else c++;
            win.push_back(b);
            if (c == m && h == hp) {
                bool ok = true;
                int idx = 0;
                for (int v : win) if (v != pattern[idx++]) { ok = false; break; }
                if (ok) return start;
            }
        }
    }
};

