var findPattern = function(stream, pattern) {
    const MOD = (1n << 61n) - 1n, BASE = 131n;
    const m = pattern.length;
    let hp = 0n;
    for (const b of pattern) hp = (hp * BASE + BigInt(b)) % MOD;
    let power = 1n;
    for (let k = 0; k < m - 1; k++) power = power * BASE % MOD;
    let h = 0n, c = 0, start = 0;
    const win = [];
    while (true) {
        const b = BigInt(stream.next());
        h = (h * BASE + b) % MOD;
        if (c === m) {
            h = ((h - BigInt(win[0]) * power) % MOD + MOD) % MOD;
            win.shift();
            start++;
        } else c++;
        win.push(Number(b));
        if (c === m && h === hp) {
            let ok = true;
            for (let k = 0; k < m; k++) if (win[k] !== pattern[k]) { ok = false; break; }
            if (ok) return start;
        }
    }
};
